// 本 TU 显式声明边界值，避免依赖共享头的偶然包含顺序。
namespace hanmo::resident { struct BoundaryValue; }
#include "economic_facility_provider.hpp"
#include <algorithm>
#include <tuple>
namespace hanmo::resident {namespace {
bool rule(const EconomicRuleRef&a,const EconomicRuleRef&b){return std::tie(a.id,a.version,a.catalog_digest)==std::tie(b.id,b.version,b.catalog_digest);}
bool activation(const FacilityActivationReceiptRef&a,const FacilityActivationReceiptRef&b){return a.receipt_id==b.receipt_id&&a.source_schema==b.source_schema;}
bool base(const EconomicFacilityBaseBinding&a,const EconomicFacilityBaseBinding&b){if(a.index()!=b.index())return false;return std::visit([&](const auto&x){using T=std::decay_t<decltype(x)>;const auto&y=std::get<T>(b);if constexpr(std::is_same_v<T,OriginalConditionBaseSlot>)return x.condition_ref==y.condition_ref&&rule(x.original_slot_definition_ref,y.original_slot_definition_ref);else if constexpr(std::is_same_v<T,InstalledServiceUnits>)return x.units==y.units&&rule(x.installed_definition_ref,y.installed_definition_ref);else return activation(x.activation_receipt_ref,y.activation_receipt_ref)&&x.capacity_unit_id==y.capacity_unit_id;},a);}
bool units(const std::vector<FacilityPhysicalUnitDefinition>&a,const std::vector<FacilityPhysicalUnitDefinition>&b){if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i){const auto&x=a[i];const auto&y=b[i];if(x.unit_key!=y.unit_key||x.capacity_unit_id!=y.capacity_unit_id||x.physical_position_key!=y.physical_position_key||x.allowed_purpose_refs.size()!=y.allowed_purpose_refs.size())return false;for(std::size_t n=0;n<x.allowed_purpose_refs.size();++n)if(!rule(x.allowed_purpose_refs[n],y.allowed_purpose_refs[n]))return false;}return true;}
bool layout(const EconomicFacilityPhysicalLayout&a,const EconomicFacilityPhysicalLayout&b){if(a.index()!=b.index())return false;return std::visit([&](const auto&x){using T=std::decay_t<decltype(x)>;const auto&y=std::get<T>(b);if constexpr(std::is_same_v<T,AggregateFacilityLayout>)return rule(x.original_layout_rule_ref,y.original_layout_rule_ref);else if constexpr(std::is_same_v<T,IndependentFacilityUnits>)return rule(x.layout_definition_ref,y.layout_definition_ref)&&rule(x.independence_policy_ref,y.independence_policy_ref)&&units(x.unit_definitions,y.unit_definitions);else return rule(x.layout_definition_ref,y.layout_definition_ref)&&rule(x.whole_zone_policy_ref,y.whole_zone_policy_ref)&&units(x.unit_definitions,y.unit_definitions);},a);}
}
bool same_economic_facility_definition(const EconomicFacilitySlotDefinition&a,const EconomicFacilitySlotDefinition&b){return rule(a.definition_ref,b.definition_ref)&&a.asset_kind==b.asset_kind&&a.slot_kind==b.slot_kind&&a.capacity_unit_id==b.capacity_unit_id&&a.physical_capacity_identity==b.physical_capacity_identity&&base(a.base_binding,b.base_binding)&&rule(a.availability_policy_ref,b.availability_policy_ref)&&rule(a.usage_policy_ref,b.usage_policy_ref)&&a.max_claim_half_days==b.max_claim_half_days&&a.retention_review_halfdays==b.retention_review_halfdays&&layout(a.physical_layout,b.physical_layout);}
Status validate_adopted_economic_facility_definitions(const CommonStore&c,const EconomicFacilitySourcesState&s,const EconomicFacilityCatalog&catalog){
 const auto&m=c.state().metadata;if(s.schema_version!=1)return common_failure("UnsupportedEconomicFacilitySourceSchema");if(catalog.identity.content_digest!=m.content_digest||catalog.identity.content_id!=m.content_id||catalog.identity.content_version!=m.content_version||catalog.identity.ruleset_id!=m.ruleset_id)return common_failure("EconomicFacilityDefinitionCatalogMismatch");
 if(s.definitions.size()!=catalog.definitions.size())return common_failure("EconomicFacilityLockedDefinitionsMissing");
 for(std::size_t i=0;i<s.definitions.size();++i){const auto&d=s.definitions[i];if(d.definition_ref.id.empty()||d.definition_ref.version<=0||d.definition_ref.catalog_digest!=catalog.identity.content_digest)return common_failure("InvalidEconomicFacilityDefinitionRef",d.definition_ref.id);for(std::size_t n=0;n<i;++n)if(rule(d.definition_ref,s.definitions[n].definition_ref))return common_failure("DuplicateFacilityDefinition",d.definition_ref.id);const EconomicFacilitySlotDefinition*original=nullptr;for(const auto&locked:catalog.definitions)if(rule(d.definition_ref,locked.definition_ref)){if(original)return common_failure("DuplicateFacilityDefinition",d.definition_ref.id);original=&locked;}if(!original||!same_economic_facility_definition(d,*original))return common_failure("EconomicFacilityDefinitionSourceMismatch",d.definition_ref.id);}
 return common_success();
}
Status adopt_locked_economic_facility_definitions_in_candidate(const CommonStore&c,EconomicFacilitySourcesState&s,const EconomicFacilityCatalog&catalog){
 if(s.schema_version!=1)return common_failure("UnsupportedEconomicFacilitySourceSchema");
 if(s.definitions.empty()&&!catalog.definitions.empty()){if(!s.facilities.empty()||!s.physical_bindings.empty()||!s.capacity_sources.empty()||!s.retention_transitions.empty())return common_failure("EconomicFacilityDefinitionInitialAdoptionRequired");s.definitions=catalog.definitions;}
 return validate_adopted_economic_facility_definitions(c,s,catalog);
}
}
